#endif

	// Move constructor
	Surface(Surface&& other) noexcept;

	// Move assignment
	Surface& operator=(Surface&& other) noexcept;

	// Deleted copy operations
	Surface(const Surface&) = delete;
	Surface& operator=(const Surface&) = delete;

	// Destructor
	~Surface();

	// event handling
	void poll_events();
	void dispatch_event(const SurfaceEvent& event);
	EventManager& get_event_manager();
	EventManager::EventListenerHandle* add_event_listener(EventType type, EventCallback handler, int priority = 0);

