// create a material from a file (.zip, .rar, .7z, .mtl)
Material::Material(const std::string& relative_filepath) : unique_ID(next_unique_ID++) {
	// Dynamically construct the full absolute path to the file.
	std::filesystem::path project_root = get_executable_directory() / "..";
	std::filesystem::path full_path = project_root / relative_filepath;
	std::string base_dir = full_path.string();

	if (!std::filesystem::exists(full_path)) {
		Log::error("in Material constructor: file not found at ", base_dir);
		exit(1);
	}

	// Get the file extension and convert it to lowercase for case-insensitive matching
	std::string extension = full_path.extension().string();
	std::transform(
		extension.begin(),
		extension.end(),
		extension.begin(),
		[](unsigned char c) { return (char)std::tolower(c); }
	);

	// load based on extension
	if (extension == ".zip" || extension == ".7z") {
		
	}
	else if (extension == ".rar") {
		
	}
	else if (extension == ".mtl") {

	}
	else {
		Log::warning("in Material constructor: unsupported file extension '", extension, "' in file '", base_dir, "'.");
		*this = std::move(Material()); // initialize to default material
		return;
	}
}

// Move constructor
Material::Material(Material&& other) noexcept :
	ambient(std::move(other.ambient)),
	specular(std::move(other.specular)),
	transmittance(std::move(other.transmittance)),
	emission(std::move(other.emission)),
	base_color(std::move(other.base_color)),
	uv_transform(std::move(other.uv_transform)),
	attenuation_color(other.attenuation_color),
	uv_rotation(other.uv_rotation),
	shininess(other.shininess),
	ior(other.ior),
	dissolve(other.dissolve),
	roughness(other.roughness),
	metallic(other.metallic),
	diffuse_factor(other.diffuse_factor),
	glossiness_factor(other.glossiness_factor),
	specular_factor(other.specular_factor),
	clearcoat_factor(other.clearcoat_factor),
	clearcoat_roughness(other.clearcoat_roughness),
	sheen_factor(other.sheen_factor),
	alpha_cutoff(other.alpha_cutoff),
	transmission_factor(other.transmission_factor),
	thickness_factor(other.thickness_factor),
	attenuation_distance(other.attenuation_distance),
	illum(other.illum),
	alpha_mode(other.alpha_mode),
	unique_ID(other.unique_ID),
	texIDs(std::move(other.texIDs)) {
	Log::debug("Material move constructor invoked. Moving from '&other' = ", &other, ", constructing at 'this' = ", this, ", unique_ID = ", unique_ID, ".");
}

// Move assignment
Material& Material::operator=(Material&& other) noexcept {
	if (this != &other) {
		Log::debug("Material move assignment invoked. Moving from '&other' = ", &other, " to 'this' = ", this, ", unique_ID = ", other.unique_ID, ".");
		this->ambient = std::move(other.ambient);
		this->specular = std::move(other.specular);
		this->transmittance = std::move(other.transmittance);
		this->emission = std::move(other.emission);
		this->base_color = std::move(other.base_color);
		this->uv_transform = std::move(other.uv_transform);
		this->attenuation_color = std::move(other.attenuation_color);
		this->uv_rotation = other.uv_rotation;
		this->shininess = other.shininess;
		this->ior = other.ior;
		this->dissolve = other.dissolve;
		this->roughness = other.roughness;
		this->metallic = other.metallic;
		this->diffuse_factor = other.diffuse_factor;
		this->glossiness_factor = other.glossiness_factor;
		this->specular_factor = other.specular_factor;
		this->clearcoat_factor = other.clearcoat_factor;
		this->clearcoat_roughness = other.clearcoat_roughness;
		this->sheen_factor = other.sheen_factor;
		this->alpha_cutoff = other.alpha_cutoff;
		this->transmission_factor = other.transmission_factor;
		this->thickness_factor = other.thickness_factor;
		this->attenuation_distance = other.attenuation_distance;
		this->illum = other.illum;
		this->alpha_mode = other.alpha_mode;
		this->unique_ID = other.unique_ID;
		this->texIDs = std::move(other.texIDs);
	}
	return *this;
}

// Copy constructor
Material::Material(const Material& other) :
	ambient(other.ambient),
	specular(other.specular),
	transmittance(other.transmittance),
	emission(other.emission),
	base_color(other.base_color),
	shininess(other.shininess),
	ior(other.ior),
	dissolve(other.dissolve),
	roughness(other.roughness),
	metallic(other.metallic),
	diffuse_factor(other.diffuse_factor),
	glossiness_factor(other.glossiness_factor),
	specular_factor(other.specular_factor),
	clearcoat_factor(other.clearcoat_factor),
	alpha_cutoff(other.alpha_cutoff),
	illum(other.illum),
	unique_ID(next_unique_ID++), // all properties are copied, except the ID, which must be unique
	texIDs(other.texIDs) {
	Log::debug("Material copy constructor invoked. Copying from '&other' = ", &other, ", constructing at 'this' = ", this, ", unique_ID = ", unique_ID, ".");
}

// Copy assignment
Material& Material::operator=(const Material& other) {
	if (this != &other) {
		Log::debug("Material copy assignment invoked. Copying from '&other' = ", &other, " to 'this' = ", this, ", unique_ID = ", other.unique_ID, ".");
		this->ambient = other.ambient;
		this->specular = other.specular;
		this->transmittance = other.transmittance;
		this->emission = other.emission;
		this->base_color = other.base_color;
		this->shininess = other.shininess;
		this->ior = other.ior;
		this->dissolve = other.dissolve;
		this->roughness = other.roughness;
		this->metallic = other.metallic;
		this->diffuse_factor = other.diffuse_factor;
		this->glossiness_factor = other.glossiness_factor;
		this->specular_factor = other.specular_factor;
		this->clearcoat_factor = other.clearcoat_factor;
		this->alpha_cutoff = other.alpha_cutoff;
		this->illum = other.illum;
		// unique_ID is not copied to maintain uniqueness
		this->texIDs = other.texIDs;
	}
	return *this;
}

int Material::get_unique_ID() const {
	return unique_ID;
}

