#endif

// provides a reference to a timeline semaphore owned by the VulkanManager singleton;
// this can be helpful to make sure the semaphore's lifetime exceeds local function scopes;
Semaphore& VulkanManager::get_timeline_semaphore(uint64_t initial_value, VkPipelineStageFlagBits2 wait_dst_stage_mask, VkPipelineStageFlagBits2 signal_dst_stage_mask) {
	uint32_t index = static_cast<uint32_t>(timeline_semaphores.size());
	timeline_semaphores.emplace_back(std::make_unique<Semaphore>(*device, initial_value, wait_dst_stage_mask, signal_dst_stage_mask));
	return *timeline_semaphores[index];
}

// provides a reference to a binary semaphore owned by the VulkanManager singleton;
// this can be helpful to make sure the semaphore's lifetime exceeds local function scopes;
Semaphore& VulkanManager::get_binary_semaphore(VkPipelineStageFlagBits2 wait_dst_stage_mask, VkPipelineStageFlagBits2 signal_dst_stage_mask) {
	uint32_t index = static_cast<uint32_t>(binary_semaphores.size());
	binary_semaphores.emplace_back(std::make_unique<Semaphore>(*device, wait_dst_stage_mask, signal_dst_stage_mask));
	return *binary_semaphores[index];
}

